def transform(grid):
    g = [row[:] for row in grid]
    bg = max(set(x for row in g for x in row), key=lambda x: sum(r.count(x) for r in g))
    color = next(x for x in set(x for row in g for x in row) if x != bg)
    for row in g:
        inds = [j for j, x in enumerate(row) if x == color]
        for a, b in zip(inds, inds[1:]):
            if b - a > 1 and all(row[j] == bg for j in range(a + 1, b)):
                for j in range(a + 1, b):
                    row[j] = 4
    return g
